def filter_products(products: list[dict[str, object]], filters: dict[str, object] | None) -> list[dict[str, object]]:
    """Filter a list of product dictionaries using AND-combined conditions.

    Business intent:
        This function emulates an e-commerce search/filter endpoint where multiple
        filters are applied together (logical AND) and results preserve input order.

    Inputs:
        - products: list of dicts. Each product is expected to have keys:
            - "price": int or float
            - "category": str
            - "in_stock": bool
          Products missing required keys or with invalid value types are treated as non-matching.

        - filters: a dict (or None) that may include the following optional keys:
            - "price_min": number, inclusive lower bound
            - "price_max": number, inclusive upper bound
            - "category": str, exact match
            - "in_stock": bool, exact match
          Unknown keys are ignored.

    Behavior:
        - All provided filters are combined with logical AND.
        - If filters is None or empty, return a shallow copy of products.
        - If "price_min" > "price_max", no product matches.

    Examples:
        filter_products(
            [{"price": 10, "category": "book", "in_stock": True}],
            {"price_min": 10, "category": "book"}
        ) -> [{"price": 10, "category": "book", "in_stock": True}]

        filter_products(
            [{"price": 10, "category": "book", "in_stock": True}],
            {"in_stock": False}
        ) -> []
    """

    if filters is None:
        filters = {}

    # Empty filter set should behave like "no filtering".
    if not filters:
        return list(products)

    def _is_number(x: object) -> bool:
        # Note: bool is a subclass of int in Python; exclude it explicitly.
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    price_min = filters.get("price_min", None)
    price_max = filters.get("price_max", None)
    category = filters.get("category", None)
    in_stock = filters.get("in_stock", None)

    if price_min is not None and not _is_number(price_min):
        raise TypeError("price_min must be a number")
    if price_max is not None and not _is_number(price_max):
        raise TypeError("price_max must be a number")
    if category is not None and not isinstance(category, str):
        raise TypeError("category must be a string")
    if in_stock is not None and not isinstance(in_stock, bool):
        raise TypeError("in_stock must be a boolean")

    if price_min is not None and price_max is not None and price_min > price_max:
        return []

    result: list[dict[str, object]] = []

    for p in products:
        if not isinstance(p, dict):
            continue

        if "price" not in p or "category" not in p or "in_stock" not in p:
            continue

        price = p.get("price")
        cat = p.get("category")
        stock = p.get("in_stock")

        if not _is_number(price) or not isinstance(cat, str) or not isinstance(stock, bool):
            continue

        if price_min is not None and price < price_min:
            continue
        if price_max is not None and price > price_max:
            continue
        if category is not None and cat != category:
            continue
        if in_stock is not None and stock != in_stock:
            continue

        result.append(p)

    return result

